// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint128 firstAmount, uint128 secondAmount, address actor) public {
        vm.assume(firstAmount <= VALUE_CAP);
        vm.assume(secondAmount <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(firstAmount > 0 && secondAmount > 0);
        uint256 total = uint256(firstAmount) + uint256(secondAmount);
        vm.deal(actor, total);

        vm.prank(actor);
        c.Put{value: firstAmount}(0);
        vm.prank(actor);
        c.Put{value: secondAmount}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == total);
    }
}
